/**
 * @description when .ts files have no explicit exports, it will not treat the file as a module.
 * standard workaround is to just export an empty object to force the behaviour
 * @link https://github.com/microsoft/TypeScript/issues/18232#issuecomment-326912884
 *  */
export {};
declare global {
    interface Number {
        clamp(this: number, min?: number, max?: number): number;
        remapClamp(this: number, low: number, high: number, remapLow?: number, remapHigh?: number): number;
        remap(this: number, low: number, high: number, remapLow?: number, remapHigh?: number): number;
        smoothStep(this: number, clamp: boolean): number;
        smootherStep(this: number, clamp: boolean): number;
        hasSomeFlags(this: number, ...flags: number[]): boolean;
        hasAllFlags(this: number, ...flags: number[]): boolean;
        roundToNearestMultiple(this: number, multiple: number): number;
        interpolate(this: number, target: number, t: number): number;
        interpolateDelta(this: number, target: number, t: number, dt: number): number;
        mod(this: number, m: number): number;
    }
}
